import '../exception.dart';
import '../reflector.dart';

/// Marks a class for `package:angel3_container_generator`, which generates the
/// [ReflectionData] a [StaticReflector] needs to construct it, so that
/// `Container.make` works without `dart:mirrors`.
class Injectable {
  const Injectable();
}

/// Marks a class for `package:angel3_container_generator`; see [Injectable].
const Injectable injectable = Injectable();

/// Reflection information about some types and functions, as generated by
/// `package:angel3_container_generator`. Combine the data of several libraries
/// with [StaticReflector.combine].
class ReflectionData {
  final Map<Type, ReflectedType> types;
  final Map<Function, ReflectedFunction> functions;

  const ReflectionData({this.types = const {}, this.functions = const {}});
}

/// A [ReflectedType] that knows only its name and [Type].
class StaticReflectedType extends ReflectedType {
  StaticReflectedType(String name, Type reflectedType)
    : super(name, const [], reflectedType);

  @override
  bool isAssignableTo(ReflectedType? other) =>
      other != null && other.reflectedType == reflectedType;

  @override
  ReflectedInstance newInstance(
    String constructorName,
    List positionalArguments, [
    Map<String, dynamic> namedArguments = const {},
    List<Type> typeArguments = const [],
  ]) => throw ReflectionException(
    '$name is not a class, and therefore cannot be instantiated.',
  );
}

/// Calls a class's default constructor with the arguments `Container.make`
/// resolved; a positional or named argument that is left out keeps its
/// default value.
typedef StaticConstructor = Object? Function(
  List positional,
  Map<String, dynamic> named,
);

/// Reads a public member of an instance by name, through generated code
/// instead of reflection: a field or getter, as its value, or a method, as a
/// tear-off; or returns [noStaticMember] if the instance has none of [name].
typedef StaticMemberReader = Object? Function(Object instance, String name);

/// Returned by a [StaticMemberReader] for a name that is no member of the
/// instance, as a member may itself be `null`.
const Object noStaticMember = _NoStaticMember();

class _NoStaticMember {
  const _NoStaticMember();

  @override
  String toString() => 'noStaticMember';
}

/// A [ReflectedClass] whose default constructor is called, and whose methods
/// are read, through generated code instead of reflection.
class StaticReflectedClass extends ReflectedClass {
  /// Calls the default constructor, or `null` when the class has none that
  /// can be called (e.g. it is abstract).
  final StaticConstructor? create;

  /// Reads a member of an instance of this class by name, or returns
  /// [noStaticMember] if it has none of that name.
  final StaticMemberReader? getMember;

  /// [annotations] are the class's, as values; [methods] its public instance
  /// methods, as [declarations].
  StaticReflectedClass(
    String name,
    Type reflectedType, {
    List<ReflectedParameter>? parameters,
    this.create,
    this.getMember,
    List<Object> annotations = const [],
    List<StaticReflectedFunction> methods = const [],
  }) : super(
         name,
         const [],
         [for (var a in annotations) StaticReflectedInstance.of(a)],
         [
           if (create != null)
             StaticReflectedFunction('', parameters ?? const []),
         ],
         [for (var m in methods) ReflectedDeclaration(m.name, false, m)],
         reflectedType,
       );

  @override
  bool isAssignableTo(ReflectedType? other) =>
      other != null && other.reflectedType == reflectedType;

  @override
  ReflectedInstance newInstance(
    String constructorName,
    List positionalArguments, [
    Map<String, dynamic> namedArguments = const {},
    List<Type> typeArguments = const [],
  ]) {
    var create = this.create;
    if (create == null || (constructorName != '' && constructorName != name)) {
      throw ReflectionException(
        '$name has no constructor named "$constructorName" that can be called '
        'without reflection.',
      );
    }
    return StaticReflectedInstance(
      create(positionalArguments, namedArguments),
      this,
    );
  }
}

/// A [ReflectedFunction] that describes a function or method, but cannot be
/// invoked.
class StaticReflectedFunction extends ReflectedFunction {
  /// [annotations] are the function's, as values.
  StaticReflectedFunction(
    String name,
    List<ReflectedParameter> parameters, {
    List<Object> annotations = const [],
  }) : super(
         name,
         const [],
         [for (var a in annotations) StaticReflectedInstance.of(a)],
         parameters,
         false,
         false,
       );

  @override
  ReflectedInstance invoke(Invocation invocation) =>
      throw UnsupportedError('$name cannot be invoked without reflection.');
}

/// A [ReflectedParameter] whose annotations are given as values.
class StaticReflectedParameter extends ReflectedParameter {
  StaticReflectedParameter(
    String name,
    ReflectedType type, {
    required bool isRequired,
    required bool isNamed,
    super.hasDefaultValue,
    List<Object> annotations = const [],
  }) : super(
         name,
         [for (var a in annotations) StaticReflectedInstance.of(a)],
         type,
         isRequired,
         isNamed,
       );
}

/// A [ReflectedInstance] that wraps a value, such as a constructed object or
/// an annotation.
class StaticReflectedInstance extends ReflectedInstance {
  StaticReflectedInstance(Object? reflectee, ReflectedClass clazz)
    : super(clazz, clazz, reflectee);

  /// Wraps [value], described only by its runtime type (enough to match an
  /// annotation by type).
  factory StaticReflectedInstance.of(Object? value) => StaticReflectedInstance(
    value,
    StaticReflectedClass(value.runtimeType.toString(), value.runtimeType),
  );

  /// Reads a member through the [StaticReflectedClass.getMember] of [clazz].
  ///
  /// Throws a [ReflectionException] if it has none of [name].
  @override
  ReflectedInstance getField(String name) {
    var clazz = this.clazz;
    var getMember = clazz is StaticReflectedClass ? clazz.getMember : null;
    var reflectee = this.reflectee;
    if (getMember == null || reflectee == null) {
      throw UnsupportedError(
        'Members of ${clazz.name} cannot be read without reflection.',
      );
    }
    var value = getMember(reflectee, name);
    if (identical(value, noStaticMember)) {
      throw ReflectionException('${clazz.name} has no member named "$name".');
    }
    return StaticReflectedInstance.of(value);
  }
}
